
.character-detail-modal {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  animation: fadeIn 0.3s ease-out;
}

.character-detail-content {
  background: linear-gradient(135deg, var(--warm-bg-light) 0%, var(--warm-bg-dark) 100%);
  border: 1px solid var(--border-color);
  border-radius: 0.75rem;
  max-width: 90%;
  max-height: 80vh;
  overflow-y: auto;
  box-shadow: 0 8px 32px var(--warm-shadow);
  animation: slideIn 0.3s ease-out;
}

.character-detail-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 1.25rem;
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  background: linear-gradient(135deg, var(--warm-bg-dark) 0%, var(--warm-bg-light) 100%);
  z-index: 1;
}

.character-name {
  font-family: var(--font-title);
  font-size: 1.25rem;
  color: var(--text-title);
  letter-spacing: 2px;
}

.character-detail-close {
  font-size: 1.25rem;
  color: var(--text-secondary);
  cursor: pointer;
  transition: color 0.3s ease;
  padding: 0.25rem;

  &:hover {
    color: var(--accent-color);
  }
}

.character-detail-body {
  padding: 1rem 1.25rem;
}

.character-detail-info {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
}

.info-item {
  display: flex;
  flex-direction: column;
}

.info-label {
  font-family: var(--font-title);
  font-size: 0.75rem;
  color: var(--user-color-primary);
  margin-bottom: 0.2rem;
  letter-spacing: 1px;
}

.info-value {
  font-family: var(--font-serif);
  font-size: 0.8rem;
  color: var(--text-primary);
  line-height: 1.4;
  word-break: break-all;
}

@media (max-width: 768px) {
  .character-detail-content {
    max-width: 95%;
    max-height: 85vh;
  }

  .character-detail-info {
    grid-template-columns: 1fr;
  }
}
